### Docs

`.env.example`:

```dotenv
# DATA_DIR overrides where 9router stores its state. Leave it unset to use the
# default (~/.9router).
#
# Fail-fast (DF-9ROUTER-2): if DATA_DIR is set but cannot be created or written
# to, 9router now REFUSES TO START rather than silently falling back to
# ~/.9router. Silent fallback could read/write a different, possibly live
# instance. Fix the path, or unset DATA_DIR.
# DATA_DIR=/var/lib/9router
# DATA_DIR=C:\9router-data
DATA_DIR=
```

README: document that a set-but-unusable `DATA_DIR` **throws at startup** and never falls back; unset to use the default; ESM and CJS copies must change together.

## Tests

Fixtures are root-safe (file-as-parent yields `ENOTDIR`/`EEXIST` for root too); the permission test is skipped when `geteuid() === 0`; the CJS constant is evaluated at require time so each scenario busts `require.cache`.

`test/dataDir.test.mjs` — key cases:

```js
test('unset DATA_DIR keeps the default', () => {
  assert.equal(resolveDataDir({ env: {} }), DEFAULT_DATA_DIR);
  assert.equal(resolveDataDir({ env: { DATA_DIR: '' } }), DEFAULT_DATA_DIR);
});

test('configured DATA_DIR that is writable is used and created', () => {
  const target = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'r-')), 'nested', 'state');
  assert.equal(resolveDataDir({ env: { DATA_DIR: target } }), path.resolve(target));
});

test('file-as-parent fixture fails fast (root-safe)', () => {
  const base = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  const blocker = path.join(base, 'blocker');
  fs.writeFileSync(blocker, 'file');
  const target = path.join(blocker, 'child');
  assert.throws(() => resolveDataDir({ env: { DATA_DIR: target } }), (err) => {
    assert.ok(err instanceof DataDirError);
    assert.equal(err.code, 'ERR_DATA_DIR_UNUSABLE');
    assert.match(err.message, /Refusing to fall back/);
    assert.ok(err.message.includes(path.resolve(target)));
    assert.ok(['ENOTDIR', 'EEXIST', 'ENOENT'].includes(err.causeCode));
    assert.match(err.message, /Remedy/);
    return true;
  });
});

test('chmod 0o500 (non-writable) fails fast',
  { skip: process.geteuid && process.geteuid() === 0 ? 'running as root' : false },
  () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
    fs.chmodSync(dir, 0o500);
    try {
      assert.throws(() => resolveDataDir({ env: { DATA_DIR: dir } }),
        (err) => err instanceof DataDirError && err.causeCode === 'EACCES');
    } finally { fs.chmodSync(dir, 0o700); }
  });

test('Unix path on Windows warns and keeps the default', () => {
  const warnings = [];
  const dir = resolveDataDir({
    env: { DATA_DIR: '/var/lib/9router' }, platform: 'win32',
    warn: (m) => warnings.push(m),
  });
  assert.equal(dir, DEFAULT_DATA_DIR);
  assert.match(warnings[0], /win32/);
});
```

`test/paths.test.cjs` — CJS with cache bust:

```js
const MODULE = path.resolve(__dirname, '..', 'src', 'mitm', 'paths.js');
const load = () => { delete require.cache[require.resolve(MODULE)]; return require(MODULE); };

test('CJS: file-as-parent fails fast (require.cache busted)', () => {
  const blocker = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'r-')), 'blocker');
  fs.writeFileSync(blocker, 'file');
  process.env.DATA_DIR = path.join(blocker, 'child');
  try {
    assert.throws(() => load(), (err) =>
      err.name === 'DataDirError' && err.code === 'ERR_DATA_DIR_UNUSABLE' &&
      ['ENOTDIR', 'EEXIST', 'ENOENT'].includes(err.causeCode));
  } finally {
    delete process.env.DATA_DIR;
    delete require.cache[require.resolve(MODULE)];
  }
});
```

## Verification (actually executed)

```bash
node --test test/dataDir.test.mjs test/paths.test.cjs
```

Result — Linux, uid 1000 (EACCES test runs, not skipped), Node v22.23.2:

```
# tests 10   # pass 10   # fail 0   # skipped 0
```

Before/after with a file-blocked parent (`/tmp/demo/not-a-dir/state`):

```
# pre-fix:  warn + silent fallback
[9router] DATA_DIR "/tmp/demo/not-a-dir/state" unusable (ENOTDIR); using default /home/kara/.9router
old result: /home/kara/.9router

# post-fix: fail fast
DataDirError: DATA_DIR "/tmp/demo/not-a-dir/state" is not usable: ENOTDIR
Refusing to fall back to the default data directory "/home/kara/.9router" ...
Remedy: make "/tmp/demo/not-a-dir/state" an existing, writable directory ...
err.code === 'ERR_DATA_DIR_UNUSABLE'
```

## Rollout notes

- Land both files in one commit; there is no shared runtime module, and drift reintroduces the bug on one entry point.
- `DATA_DIR` is read at module load time; set it before importing 9router (tests call `resolveDataDir` or bust the CJS require cache).
- The Windows Unix-path guard is the *only* remaining silent fallback; it is retained for legacy config compatibility and always warns.
